questions.starter_code:
const width = "42px";
const weight = "3.14kg";
// convert both

questions.answer:
const width = "42px";
const weight = "3.14kg";

const px = parseInt(width, 10);
const kg = parseFloat(weight);

console.log(px, kg);       // 42 3.14
console.log(Number(width)); // NaN

`Number()` requires the whole string to be numeric, so `Number("42px")` is `NaN`. `parseInt`/`parseFloat` read the leading number and stop at the first invalid character. Always pass radix `10` to `parseInt`.

questions.starter_code:
const config = { db: { host: "localhost", port: 5432 } };
const copy = { ...config };
copy.db.host = "prod.db";
console.log(config.db.host); // "prod.db" — wrong

questions.answer:
Use `structuredClone` for a real deep copy:

const config = { db: { host: "localhost", port: 5432 } };
const copy = structuredClone(config);
copy.db.host = "prod.db";

console.log(config.db.host); // "localhost"
console.log(copy.db.host);   // "prod.db"

Spread only copies the top level, so `copy.db` is the same nested object. `structuredClone` handles nested objects and arrays (but not functions or DOM nodes).

questions.starter_code:
function isEqual(a, b) {
  // compare keys and values
}

console.log(isEqual({ name: "Kakade" }, { name: "Kakade" })); // true
console.log(isEqual({ name: "Kakade" }, { name: "Asha" }));   // false

questions.answer:
function isEqual(a, b) {
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  if (keysA.length !== keysB.length) return false;

  return keysA.every(
    (key) => Object.hasOwn(b, key) && a[key] === b[key]
  );
}

console.log(isEqual({ name: "Kakade" }, { name: "Kakade" })); // true
console.log(isEqual({ name: "Kakade" }, { name: "Asha" }));   // false

`===` on two objects compares references, so `{ name: "Kakade" } === { name: "Kakade" }` is false. Compare keys and primitive values instead. Nested objects would need a recursive comparison.
